; >S:KILLER-CODE; PUT "KILLER-CODE";; THE LOGIC RELATED TO THE; KILLING OF THE NASTIES;; NOTOKL = NO OF ALIENS KILLED; (GETS ZEROED AT EXIT OF ROOM);INITKL;; INITIALISE # TO KILL;LDA #0STA NOKILD;LDA KILHEXSTA ALKILL   ;* NUMBER TO KILL;LDA CLEARDBNE KILLED   ;* NO EFFECT;SED;LDA KILDEC    ;* NUM TO KILLSTA NOTOKL;CLD;; NOW FALL THROUGH AND PRINT IT;JMP OHSHIT;;-------------------------------;; THIS ROUTINE IS CALLED UNDER IRQ; TO ADD ONE TO THE NUMBER KILLED.;; IF THE NUMBER KILLED=10; THEN THE ROUTINE HANDS OVER TO; BASIC LOOP;KILLED;LDA CLEARD   ;* CLEARED THIS ONEBEQ KILOP;LDA #$30STA $D3BSTA $D3C;; YOU DON'T HAVE TO CLEAR ANY; IF YOU'VE COMPLETED THIS ROOM; DO YOU - GONK.;RTS;KILOP;INC NOKILD;OHSHIT      ;* !!;SED;LDA NOTOKL;SECSBC #1;STA NOTOKL;CLD;; LETS UPDATE THE COUNT;PHA;LSR ALSR ALSR ALSR A;ORA #$30STA $D3B;PLA;AND #15ORA #$30STA $D3C;LDA NOTOKLBEQ KILALL   ;* ALL GONE;RTS;;---------------;KILALL;LDX SCREENLDA #1STA GOTBIT,X;; WE'VE CLEARED IT !!!  WWOOOOO!;STA CLEARDSTA DOSFX;JSR TRANSF;; COPY JIG IN THE MIDDLE TO; THE ONE ON THE RIGHT;RTS;;--------------;CLSSND;LDA SNDFLGBEQ YOGUP;LDA #%00111111STA VOL;YOGUP;LDA #3STA WORK;LDA #0STA WORK+1;GASTE1;LDX #0;GASREE;INC BORDER;DEXBNE GASREE;LDA WORK+1STA SOU2LO;EOR #$FFSTA SOU1LO;LDA WORKAND #3STA SOU2HI;EOR #$FFAND #3;ORA SOU1HISTA SOU1HI;DEC WORK+1BNE GASTE1;DEC WORKBNE GASTE1;LDA #0STA VOL;LDA #$11STA BORDER;RTS;;;;;.END